//! Phase 3 text-extraction acceptance tests.
//!
//! Fixtures are generated by `tests/gen_text_fixtures.py` (minimal hand-built
//! PDFs, committed). They cover the plan's acceptance criteria:
//!
//! - `text_rtl.pdf` — Hebrew word emitted in *visual* order (Type0
//!   Identity-H + ToUnicode); extraction must recover logical order.
//! - `text_columns.pdf` — two columns with aligned baselines; column-aware
//!   extraction must preserve column boundaries.
//! - `text_rotated.pdf` — horizontal + 90°/180°/270° runs; rotated lines
//!   must be grouped per orientation.

use pdf_core::document::catalog::Catalog;
use pdf_core::document::page::Page;
use pdf_core::parser::objects::PdfDocument;
use pdf_core::text::TextExtractor;

fn extract(fixture: &str) -> (PdfDocument, TextExtractor) {
    let path = format!("{}/tests/fixtures/{}", env!("CARGO_MANIFEST_DIR"), fixture);
    let bytes = std::fs::read(&path)
        .unwrap_or_else(|e| panic!("fixture {fixture} missing (run gen_text_fixtures.py): {e}"));
    let doc = PdfDocument::parse(bytes).unwrap_or_else(|e| panic!("parse {fixture}: {e}"));
    let catalog = Catalog::from_document(&doc).expect("catalog");
    let page_dict = catalog.get_page_dict(&doc, 0).expect("page dict");
    let page = Page::from_dict(&doc, &page_dict).expect("page");
    let extractor = TextExtractor::extract_from_page(&doc, &page).expect("extract");
    (doc, extractor)
}

#[test]
fn rtl_fixture_extracts_logical_order() {
    let (_, extractor) = extract("text_rtl.pdf");
    // Visual stream order is "םולש" (leftmost glyph first); logical is שלום.
    assert_eq!(extractor.plain_text(), "שלום");
}

#[test]
fn columns_fixture_preserves_column_boundaries() {
    let (_, extractor) = extract("text_columns.pdf");
    // Columns left-to-right, lines top-to-bottom within each column.
    assert_eq!(
        extractor.plain_text_columns(40.0),
        "Alpha beta\nEpsilon\nGamma delta\nZeta eta"
    );
    // The plain (non-column) flow interleaves the columns — sanity that the
    // fixture really has aligned baselines.
    assert_eq!(
        extractor.plain_text(),
        "Alpha beta Gamma delta\nEpsilon Zeta eta"
    );
}

#[test]
fn rotated_fixture_groups_per_orientation() {
    let (_, extractor) = extract("text_rotated.pdf");
    let rotated = extractor.rotated_lines();
    let mut by_deg: Vec<(u16, String)> = rotated
        .into_iter()
        .map(|(deg, lines)| {
            let text = lines
                .iter()
                .map(|l| {
                    l.words
                        .iter()
                        .map(|w| w.text.as_str())
                        .collect::<Vec<_>>()
                        .join(" ")
                })
                .collect::<Vec<_>>()
                .join("\n");
            (deg, text)
        })
        .collect();
    by_deg.sort_by_key(|(deg, _)| *deg);
    assert_eq!(
        by_deg,
        vec![
            (90, "Upward".to_string()),
            (180, "Flipped".to_string()),
            (270, "Downward".to_string()),
        ]
    );
    // Horizontal text flows through the normal path; the two y=50 runs
    // share a baseline, so the plain flow clusters them into one line.
    assert_eq!(
        extractor.plain_text(),
        "Flipped\nHorizontal\nUpward Downward"
    );
}
